const routes = {"/":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Plant Attendance</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n  </head>\n  <body>\n    <section class=\"login-screen\" id=\"loginScreen\">\n      <div class=\"login-panel\">\n        <div class=\"brand compact\">\n          <div class=\"brand-mark\">PA</div>\n          <div>\n            <h1>Plant Attendance</h1>\n            <p>Secure line-wise login</p>\n          </div>\n        </div>\n        <div class=\"login-form\">\n          <label>\n            User ID\n            <input id=\"loginUser\" autocomplete=\"username\" placeholder=\"User ID\">\n          </label>\n          <label>\n            Password\n            <input id=\"loginPass\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Password\">\n          </label>\n          <button class=\"primary-btn\" id=\"loginBtn\">Login</button>\n        </div>\n        <p class=\"hint\" id=\"loginHint\">Production logins are loaded from the Postgres database. Import existing users before plant use.</p>\n      </div>\n    </section>\n\n    <div class=\"app-shell\">\n      <aside class=\"sidebar\">\n        <button class=\"menu-btn\" id=\"menuBtn\" type=\"button\" aria-expanded=\"false\" aria-label=\"Options menu\" title=\"Options menu\">\n          <span></span>\n          <span></span>\n          <span></span>\n        </button>\n\n        <div class=\"brand\">\n          <div class=\"brand-mark\">PA</div>\n          <div>\n            <h1>Plant Attendance</h1>\n            <p>Line-wise daily manpower</p>\n          </div>\n        </div>\n\n        <nav class=\"nav-tabs\" aria-label=\"Main views\">\n          <button class=\"nav-tab active\" data-view=\"supervisor\" title=\"Supervisor attendance\">\n            <span>Scan</span>\n          </button>\n          <button class=\"nav-tab\" data-view=\"admin\" title=\"Admin dashboard\">\n            <span>Admin</span>\n          </button>\n          <button class=\"nav-tab\" data-view=\"blacklist\" title=\"Absenteeism check\">\n            <span>Blacklist</span>\n          </button>\n          <button class=\"nav-tab\" data-view=\"master\" title=\"Operator master\">\n            <span>Master</span>\n          </button>\n        </nav>\n\n        <div class=\"sidebar-card user-card\">\n          <span class=\"label\">Logged in</span>\n          <strong id=\"currentUserLabel\">Not logged in</strong>\n          <small id=\"currentScopeLabel\"></small>\n          <button class=\"ghost-btn\" id=\"logoutBtn\">Logout</button>\n        </div>\n\n        <div class=\"sidebar-card\">\n          <span class=\"label\">Today</span>\n          <strong id=\"todayLabel\"></strong>\n          <small>All records are saved on this device and can be exported.</small>\n        </div>\n      </aside>\n\n      <main>\n        <header class=\"topbar\">\n          <div>\n            <p class=\"eyebrow\">Morning attendance</p>\n            <h2 id=\"viewTitle\">Supervisor Scan</h2>\n          </div>\n          <div class=\"topbar-actions\">\n            <button class=\"ghost-btn\" id=\"backupBtn\" title=\"Download all backup data\">Backup</button>\n            <button class=\"primary-btn\" id=\"downloadBtn\" title=\"Download Excel-readable attendance file\">Download Excel</button>\n          </div>\n        </header>\n\n        <section class=\"view active\" id=\"supervisorView\">\n          <div class=\"toolbar\">\n            <label>\n              Date\n              <input type=\"date\" id=\"attendanceDate\">\n            </label>\n            <label>\n              Department\n              <select id=\"departmentSelect\"></select>\n            </label>\n            <label>\n              Line\n              <select id=\"lineSelect\"></select>\n            </label>\n            <label>\n              Shift\n              <select id=\"shiftSelect\">\n                <option>A</option>\n                <option>B</option>\n                <option>C</option>\n                <option>General</option>\n              </select>\n            </label>\n            <label>\n              Line Leader\n              <input id=\"supervisorName\" placeholder=\"Name\" readonly>\n            </label>\n          </div>\n\n          <div class=\"scan-grid\">\n            <section class=\"panel scanner-panel\">\n              <div class=\"panel-head\">\n                <div>\n                  <h3>Skill Card Scanner</h3>\n                  <p>Each skill card is saved automatically after scan.</p>\n                </div>\n                <button class=\"ghost-btn\" id=\"cameraBtn\" title=\"Start camera scanning\">Start Camera</button>\n              </div>\n\n              <div class=\"camera-wrap\">\n                <video id=\"scannerVideo\" muted playsinline></video>\n                <div class=\"scan-frame\"></div>\n                <div class=\"camera-empty\" id=\"cameraEmpty\">Camera scanner ready</div>\n              </div>\n\n              <div class=\"quick-entry\">\n                <input id=\"scanInput\" placeholder=\"Scanner ready for Emp. ID\">\n                <button class=\"primary-btn\" id=\"missedCardBtn\">Missed Card ID</button>\n                <button class=\"ghost-btn\" id=\"queryFromScanBtn\">Query</button>\n              </div>\n\n              <div class=\"last-scan\" id=\"lastScan\">\n                <span>No operator scanned yet.</span>\n              </div>\n            </section>\n\n            <section class=\"panel\">\n              <div class=\"panel-head\">\n                <div>\n                  <h3>Current Line Count</h3>\n                  <p>Live count for selected date, shift, department and line.</p>\n                </div>\n              </div>\n              <div class=\"metrics\">\n                <div class=\"metric\">\n                  <span>Present</span>\n                  <strong id=\"presentCount\">0</strong>\n                </div>\n                <div class=\"metric\">\n                  <span>Required</span>\n                  <strong id=\"requiredCount\">0</strong>\n                </div>\n                <div class=\"metric\">\n                  <span>Gap</span>\n                  <strong id=\"gapCount\">0</strong>\n                </div>\n              </div>\n              <div class=\"skill-summary\" id=\"skillSummary\"></div>\n            </section>\n          </div>\n\n          <section class=\"panel table-panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Line Attendance</h3>\n                <p>Names remain available as backup for admin.</p>\n              </div>\n              <button class=\"danger-btn\" id=\"clearLineBtn\">Clear Line</button>\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Time</th>\n                    <th>Emp. ID</th>\n                    <th>Name</th>\n                    <th>Current Process</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th>Status</th>\n                    <th></th>\n                  </tr>\n                </thead>\n                <tbody id=\"attendanceRows\"></tbody>\n              </table>\n            </div>\n          </section>\n        </section>\n\n        <section class=\"view\" id=\"blacklistView\">\n          <section class=\"panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Punctuality Query</h3>\n                <p>Scan or enter Emp. ID to see absent days.</p>\n              </div>\n              <button class=\"primary-btn\" id=\"queryBtn\">Query</button>\n            </div>\n            <div class=\"query-line\">\n              <input id=\"queryInput\" placeholder=\"Emp. ID, e.g. 303408\">\n              <select id=\"queryShift\">\n                <option value=\"all\">All Shifts</option>\n                <option>A</option>\n                <option>B</option>\n                <option>C</option>\n                <option>General</option>\n              </select>\n            </div>\n            <div id=\"queryResult\" class=\"query-result\">\n              <span>Enter an Emp. ID to check attendance history.</span>\n            </div>\n          </section>\n\n          <section class=\"panel table-panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Blacklist Over 20%</h3>\n                <p>Based on absenteeism in recorded line attendance sessions.</p>\n              </div>\n              <button class=\"ghost-btn\" id=\"downloadBlacklistBtn\">Download Blacklist</button>\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Emp. ID</th>\n                    <th>Name</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th>Working Sessions</th>\n                    <th>Absent</th>\n                    <th>Absent %</th>\n                    <th>Absent Days</th>\n                  </tr>\n                </thead>\n                <tbody id=\"blacklistRows\"></tbody>\n              </table>\n            </div>\n          </section>\n        </section>\n\n        <section class=\"view\" id=\"adminView\">\n          <div class=\"admin-grid\">\n            <section class=\"panel\">\n              <div class=\"panel-head\">\n                <div>\n                  <h3>Plant Summary</h3>\n                  <p>Compiled line-wise manpower count.</p>\n                </div>\n              </div>\n              <div class=\"metrics wide\">\n                <div class=\"metric\"><span>Total Present</span><strong id=\"adminTotal\">0</strong></div>\n                <div class=\"metric\"><span>Lines Covered</span><strong id=\"adminLines\">0</strong></div>\n                <div class=\"metric\"><span>Operators</span><strong id=\"adminOperators\">0</strong></div>\n              </div>\n            </section>\n            <section class=\"panel\">\n              <div class=\"panel-head\">\n                <div>\n                  <h3>Department Count</h3>\n                  <p>Ready for morning manpower review.</p>\n                </div>\n              </div>\n              <div id=\"deptBars\" class=\"bars\"></div>\n            </section>\n          </div>\n\n          <section class=\"panel table-panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Compiled Attendance</h3>\n                <p>Line totals with backup names available in export.</p>\n              </div>\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Date</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th>Shift</th>\n                    <th>Present</th>\n                    <th>Processes</th>\n                    <th>Names</th>\n                  </tr>\n                </thead>\n                <tbody id=\"adminRows\"></tbody>\n              </table>\n            </div>\n          </section>\n\n          <section class=\"panel table-panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Login Control</h3>\n                <p>Admin creates department and line-leader access.</p>\n              </div>\n              <button class=\"primary-btn\" id=\"addUserBtn\">Create Login</button>\n            </div>\n            <div class=\"operator-form login-create\">\n              <input id=\"newLoginName\" placeholder=\"Leader/Admin name\">\n              <input id=\"newLoginId\" placeholder=\"User ID\">\n              <input id=\"newLoginPass\" placeholder=\"Password\">\n              <select id=\"newLoginRole\">\n                <option value=\"supervisor\">Line Leader</option>\n                <option value=\"admin\">Admin</option>\n              </select>\n              <input id=\"newLoginDept\" placeholder=\"Department\">\n              <input id=\"newLoginLine\" placeholder=\"Line\">\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Name</th>\n                    <th>User ID</th>\n                    <th>Role</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th></th>\n                  </tr>\n                </thead>\n                <tbody id=\"userRows\"></tbody>\n              </table>\n            </div>\n          </section>\n        </section>\n\n        <section class=\"view\" id=\"masterView\">\n          <section class=\"panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Operator Master</h3>\n                <p>Import your employee list or add operators manually.</p>\n              </div>\n              <button class=\"ghost-btn\" id=\"sampleBtn\">Load Sample Master</button>\n            </div>\n            <div class=\"master-actions\">\n              <label class=\"file-import\">\n                Import CSV\n                <input type=\"file\" id=\"masterFile\" accept=\".csv,text/csv\">\n              </label>\n              <button class=\"primary-btn\" id=\"addOperatorBtn\">Add Operator</button>\n            </div>\n            <div class=\"operator-form\">\n              <input id=\"newCode\" placeholder=\"Emp. ID\">\n              <input id=\"newName\" placeholder=\"Name\">\n              <input id=\"newSkill\" placeholder=\"Current Process\">\n              <input id=\"newDept\" placeholder=\"Department\">\n              <input id=\"newLine\" placeholder=\"Line\">\n              <input id=\"newDoj\" placeholder=\"DOJ\">\n              <input id=\"newSkillLevel\" placeholder=\"Skill Level\">\n            </div>\n            <p class=\"hint\">CSV columns: emp_id, name, department, line, current_process, doj, skill_level, issued_date, renew_date. Your sample QR decodes to Emp. ID only, so details are pulled from master data.</p>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Emp. ID</th>\n                    <th>Name</th>\n                    <th>Current Process</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th>DOJ</th>\n                    <th>Skill Level</th>\n                  </tr>\n                </thead>\n                <tbody id=\"masterRows\"></tbody>\n              </table>\n            </div>\n          </section>\n        </section>\n      </main>\n    </div>\n\n    <div class=\"toast\" id=\"toast\"></div>\n    <script src=\"app.js\"></script>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":":root {\n  --bg: #f4f7f8;\n  --panel: #ffffff;\n  --ink: #172026;\n  --muted: #63717a;\n  --line: #dce5e8;\n  --brand: #116a7b;\n  --brand-strong: #0d5260;\n  --green: #18794e;\n  --amber: #a86800;\n  --red: #b42318;\n  --soft: #e8f4f1;\n  --shadow: 0 14px 32px rgba(16, 31, 36, .08);\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  min-height: 100vh;\n  background: var(--bg);\n  color: var(--ink);\n  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\n\n.login-screen {\n  position: fixed;\n  inset: 0;\n  z-index: 20;\n  display: grid;\n  place-items: center;\n  padding: 22px;\n  background: #10272d;\n}\n\n.login-screen.hidden {\n  display: none;\n}\n\n.login-panel {\n  width: min(440px, 100%);\n  display: grid;\n  gap: 22px;\n  padding: 24px;\n  color: var(--ink);\n  background: white;\n  border-radius: 8px;\n  box-shadow: 0 24px 70px rgba(0, 0, 0, .28);\n}\n\n.brand.compact {\n  color: var(--ink);\n}\n\n.brand.compact p {\n  color: var(--muted);\n}\n\n.login-form {\n  display: grid;\n  gap: 12px;\n}\n\n.app-shell.locked {\n  filter: blur(2px);\n  pointer-events: none;\n  user-select: none;\n}\n\nbutton, input, select {\n  font: inherit;\n}\n\nbutton {\n  min-height: 40px;\n  border: 0;\n  cursor: pointer;\n  font-weight: 700;\n}\n\n.app-shell {\n  display: grid;\n  grid-template-columns: 280px 1fr;\n  min-height: 100vh;\n}\n\n.sidebar {\n  background: #10272d;\n  color: white;\n  padding: 22px;\n  display: flex;\n  flex-direction: column;\n  gap: 22px;\n}\n\n.menu-btn {\n  display: none;\n}\n\n.brand {\n  display: flex;\n  gap: 12px;\n  align-items: center;\n}\n\n.brand-mark {\n  width: 46px;\n  height: 46px;\n  border-radius: 8px;\n  display: grid;\n  place-items: center;\n  background: #e8c468;\n  color: #10272d;\n  font-weight: 900;\n}\n\nh1, h2, h3, p { margin: 0; }\n\n.brand h1 {\n  font-size: 18px;\n  line-height: 1.2;\n}\n\n.brand p, .sidebar-card small, .user-card small {\n  color: #b8c9ce;\n}\n\n.nav-tabs {\n  display: grid;\n  gap: 8px;\n}\n\n.nav-tab {\n  color: #dbe8eb;\n  background: transparent;\n  border-radius: 8px;\n  padding: 12px 14px;\n  text-align: left;\n}\n\n.nav-tab.active, .nav-tab:hover {\n  color: white;\n  background: rgba(255, 255, 255, .12);\n}\n\n.sidebar-card {\n  margin-top: auto;\n  display: grid;\n  gap: 6px;\n  padding: 16px;\n  background: rgba(255, 255, 255, .08);\n  border: 1px solid rgba(255, 255, 255, .14);\n  border-radius: 8px;\n}\n\n.user-card {\n  margin-top: 0;\n}\n\n.user-card .ghost-btn {\n  margin-top: 8px;\n  width: 100%;\n}\n\n.label, .eyebrow {\n  color: var(--muted);\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: .08em;\n  font-weight: 800;\n}\n\nmain {\n  padding: 24px;\n  min-width: 0;\n}\n\n.topbar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  margin-bottom: 20px;\n}\n\n.topbar h2 {\n  font-size: 28px;\n}\n\n.topbar-actions, .panel-head, .master-actions, .quick-entry {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.panel-head {\n  justify-content: space-between;\n  margin-bottom: 16px;\n}\n\n.panel-head p, .hint {\n  color: var(--muted);\n  font-size: 14px;\n  margin-top: 4px;\n}\n\n.primary-btn, .ghost-btn, .danger-btn, .file-import {\n  border-radius: 8px;\n  padding: 10px 14px;\n  white-space: nowrap;\n}\n\n.primary-btn {\n  color: white;\n  background: var(--brand);\n}\n\n.primary-btn:hover { background: var(--brand-strong); }\n\n.ghost-btn, .file-import {\n  color: var(--brand-strong);\n  background: var(--soft);\n}\n\n.danger-btn {\n  color: white;\n  background: var(--red);\n}\n\n.view {\n  display: none;\n}\n\n.view.active {\n  display: block;\n}\n\n.toolbar {\n  display: grid;\n  grid-template-columns: repeat(5, minmax(150px, 1fr));\n  gap: 12px;\n  margin-bottom: 16px;\n}\n\nlabel {\n  display: grid;\n  gap: 6px;\n  color: var(--muted);\n  font-size: 13px;\n  font-weight: 800;\n}\n\ninput, select {\n  width: 100%;\n  min-height: 42px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  padding: 9px 10px;\n  color: var(--ink);\n  background: white;\n}\n\ninput[readonly], select:disabled {\n  color: #53646d;\n  background: #edf3f5;\n}\n\n.scan-grid, .admin-grid {\n  display: grid;\n  grid-template-columns: minmax(360px, 1.35fr) minmax(320px, .8fr);\n  gap: 16px;\n  margin-bottom: 16px;\n}\n\n.panel {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  box-shadow: var(--shadow);\n  padding: 18px;\n  min-width: 0;\n}\n\n.camera-wrap {\n  position: relative;\n  aspect-ratio: 16 / 9;\n  overflow: hidden;\n  border-radius: 8px;\n  background: #10272d;\n  margin-bottom: 14px;\n}\n\nvideo {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.camera-empty {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  color: #c9dadd;\n  background: linear-gradient(135deg, rgba(16, 39, 45, .96), rgba(28, 70, 76, .96));\n  font-weight: 800;\n}\n\n.camera-empty.hidden {\n  display: none;\n}\n\n.scan-frame {\n  position: absolute;\n  inset: 18%;\n  border: 3px solid #e8c468;\n  border-radius: 8px;\n  box-shadow: 0 0 0 999px rgba(0, 0, 0, .22);\n  pointer-events: none;\n}\n\n.quick-entry {\n  align-items: stretch;\n}\n\n.quick-entry input {\n  flex: 1;\n}\n\n.last-scan {\n  min-height: 46px;\n  margin-top: 12px;\n  padding: 12px;\n  border-radius: 8px;\n  background: #f6faf9;\n  border: 1px solid var(--line);\n  color: var(--muted);\n}\n\n.metrics {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 10px;\n  margin-bottom: 14px;\n}\n\n.metric {\n  min-height: 100px;\n  padding: 14px;\n  border-radius: 8px;\n  background: #f7fafb;\n  border: 1px solid var(--line);\n  display: grid;\n  align-content: center;\n  gap: 8px;\n}\n\n.metric span {\n  color: var(--muted);\n  font-size: 13px;\n  font-weight: 800;\n}\n\n.metric strong {\n  font-size: 32px;\n}\n\n.skill-summary, .bars {\n  display: grid;\n  gap: 8px;\n}\n\n.pill-row, .bar-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  padding: 10px 12px;\n  border-radius: 8px;\n  background: #f7fafb;\n  border: 1px solid var(--line);\n}\n\n.status {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 92px;\n  min-height: 28px;\n  border-radius: 999px;\n  padding: 4px 10px;\n  font-weight: 800;\n  font-size: 12px;\n}\n\n.status.pending { background: #fff4df; color: var(--amber); }\n.status.verified { background: #e8f6ed; color: var(--green); }\n.status.present { background: #e8f6ed; color: var(--green); }\n.status.risk { background: #fee4e2; color: var(--red); }\n\n.query-line {\n  display: grid;\n  grid-template-columns: minmax(220px, 1fr) 180px;\n  gap: 10px;\n  margin-bottom: 14px;\n}\n\n.query-result {\n  display: grid;\n  gap: 12px;\n  min-height: 78px;\n  padding: 14px;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #f7fafb;\n  color: var(--muted);\n}\n\n.query-person {\n  display: grid;\n  gap: 4px;\n}\n\n.query-person strong {\n  color: var(--ink);\n  font-size: 18px;\n}\n\n.compact-metrics {\n  margin-bottom: 0;\n}\n\n.compact-metrics .metric {\n  min-height: 82px;\n}\n\n.absent-list {\n  color: var(--ink);\n  line-height: 1.5;\n}\n\n.table-panel {\n  padding-bottom: 8px;\n}\n\n.table-wrap {\n  width: 100%;\n  overflow: auto;\n  border: 1px solid var(--line);\n  border-radius: 8px;\n}\n\ntable {\n  width: 100%;\n  border-collapse: collapse;\n  min-width: 850px;\n}\n\nth, td {\n  padding: 12px 14px;\n  border-bottom: 1px solid var(--line);\n  text-align: left;\n  font-size: 14px;\n  vertical-align: top;\n}\n\nth {\n  background: #f3f7f8;\n  color: #45545c;\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: .06em;\n}\n\ntr:last-child td {\n  border-bottom: 0;\n}\n\n.mini-btn {\n  min-height: 32px;\n  padding: 6px 10px;\n  border-radius: 8px;\n  background: #eef4f6;\n  color: var(--brand-strong);\n}\n\n.master-actions {\n  margin-bottom: 12px;\n}\n\n.file-import {\n  display: inline-flex;\n  align-items: center;\n  min-height: 40px;\n  cursor: pointer;\n}\n\n.file-import input {\n  display: none;\n}\n\n.operator-form {\n  display: grid;\n  grid-template-columns: repeat(5, 1fr);\n  gap: 10px;\n  margin-bottom: 10px;\n}\n\n.login-create {\n  grid-template-columns: repeat(6, minmax(120px, 1fr));\n}\n\n.hint {\n  margin-bottom: 14px;\n}\n\n.toast {\n  position: fixed;\n  right: 20px;\n  bottom: 20px;\n  max-width: 380px;\n  padding: 12px 14px;\n  color: white;\n  background: #10272d;\n  border-radius: 8px;\n  box-shadow: var(--shadow);\n  transform: translateY(18px);\n  opacity: 0;\n  pointer-events: none;\n  transition: .2s ease;\n}\n\n.toast.show {\n  transform: translateY(0);\n  opacity: 1;\n}\n\n@media (max-width: 1100px) {\n  .app-shell {\n    grid-template-columns: 1fr;\n  }\n\n  .sidebar {\n    position: sticky;\n    top: 0;\n    z-index: 5;\n    display: grid;\n    grid-template-columns: auto 1fr;\n    align-items: center;\n    gap: 14px;\n    padding: 14px;\n  }\n\n  .menu-btn {\n    width: 44px;\n    height: 44px;\n    min-height: 44px;\n    display: grid;\n    place-content: center;\n    gap: 5px;\n    padding: 0;\n    border-radius: 8px;\n    background: rgba(255, 255, 255, .12);\n  }\n\n  .menu-btn span {\n    width: 18px;\n    height: 2px;\n    border-radius: 2px;\n    background: #ffffff;\n  }\n\n  .sidebar .brand {\n    min-width: 0;\n  }\n\n  .sidebar .brand-mark {\n    width: 38px;\n    height: 38px;\n  }\n\n  .sidebar .brand h1 {\n    font-size: 16px;\n  }\n\n  .sidebar .brand p {\n    font-size: 13px;\n  }\n\n  .nav-tabs {\n    grid-column: 1 / -1;\n    grid-template-columns: repeat(4, minmax(0, 1fr));\n    gap: 6px;\n  }\n\n  .nav-tab {\n    min-height: 42px;\n    padding: 9px 8px;\n    text-align: center;\n  }\n\n  .sidebar-card {\n    display: none;\n  }\n\n  .user-card {\n    position: absolute;\n    top: 68px;\n    left: 14px;\n    right: 14px;\n    display: none;\n    z-index: 8;\n    margin-top: 0;\n    box-shadow: 0 18px 34px rgba(0, 0, 0, .22);\n  }\n\n  .sidebar.menu-open .user-card {\n    display: grid;\n  }\n\n  .user-card .ghost-btn {\n    width: auto;\n    justify-self: start;\n    padding-inline: 18px;\n  }\n\n  .toolbar, .scan-grid, .admin-grid, .operator-form, .login-create, .query-line {\n    grid-template-columns: 1fr 1fr;\n  }\n}\n\n@media (max-width: 720px) {\n  main {\n    padding: 14px;\n  }\n\n  .topbar, .topbar-actions, .panel-head, .quick-entry, .master-actions {\n    align-items: stretch;\n    flex-direction: column;\n  }\n\n  .toolbar, .scan-grid, .admin-grid, .operator-form, .login-create, .query-line, .metrics {\n    grid-template-columns: 1fr;\n  }\n\n  .nav-tabs { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n\n  .topbar h2 {\n    font-size: 24px;\n  }\n}\n","type":"text/css; charset=utf-8"},"/app.js":{"body":"const STORAGE_KEY = \"plant-attendance-v2\";\nconst SESSION_KEY = \"plant-attendance-current-user\";\n\nconst sampleOperators = [\n  [\"303408\", \"Sample Operator\", \"F/A\", \"Production\", \"Assembly-K2\", \"14-07-2025\", \"Level 4\", \"23-04-2026\", \"22-07-2026\"],\n  [\"OP1001\", \"Asha Patel\", \"Welding\", \"Assembly\", \"Line 1\"],\n  [\"OP1002\", \"Ravi Shah\", \"Fitting\", \"Assembly\", \"Line 1\"],\n  [\"OP1003\", \"Meena Iyer\", \"Inspection\", \"Assembly\", \"Line 1\"],\n  [\"OP1004\", \"Imran Khan\", \"Machine\", \"Machining\", \"Line 2\"],\n  [\"OP1005\", \"Nisha Rao\", \"CNC\", \"Machining\", \"Line 2\"],\n  [\"OP1006\", \"Vikram Singh\", \"Maintenance\", \"Machining\", \"Line 2\"],\n  [\"OP1007\", \"Pooja Desai\", \"Packing\", \"Dispatch\", \"Line 3\"],\n  [\"OP1008\", \"Kiran Mehta\", \"Forklift\", \"Dispatch\", \"Line 3\"],\n  [\"OP1009\", \"Suresh Kumar\", \"Quality\", \"Quality\", \"Line 4\"],\n  [\"OP1010\", \"Farah Ansari\", \"Final Audit\", \"Quality\", \"Line 4\"],\n  [\"OP1011\", \"Deepak Joshi\", \"Press\", \"Press Shop\", \"Line 5\"],\n  [\"OP1012\", \"Leena Nair\", \"Die Setting\", \"Press Shop\", \"Line 5\"]\n].map(([code, name, skill, department, line, doj = \"\", skillLevel = \"\", issuedDate = \"\", renewDate = \"\"]) => ({\n  code,\n  name,\n  skill,\n  department,\n  line,\n  doj,\n  skillLevel,\n  issuedDate,\n  renewDate\n}));\n\nconst defaultUsers = [\n];\n\nlet state = loadState();\nlet currentUser = loadCurrentUser();\nlet stream = null;\nlet detector = null;\nlet scanning = false;\nlet serverBacked = false;\nlet serverLoaded = false;\nlet lastScanValue = \"\";\nlet lastScanAt = 0;\n\nconst $ = (id) => document.getElementById(id);\nconst today = localDate();\n\n$(\"attendanceDate\").value = today;\n$(\"todayLabel\").textContent = new Date().toLocaleDateString(undefined, {\n  weekday: \"short\",\n  day: \"2-digit\",\n  month: \"short\",\n  year: \"numeric\"\n});\n\nfunction localDate(date = new Date()) {\n  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60_000);\n  return local.toISOString().slice(0, 10);\n}\n\nfunction normalizeState(parsed = {}) {\n  return {\n    operators: Array.isArray(parsed.operators) ? parsed.operators : sampleOperators,\n    attendance: Array.isArray(parsed.attendance) ? parsed.attendance : [],\n    users: Array.isArray(parsed.users) ? parsed.users : defaultUsers,\n    deletedAttendanceIds: Array.isArray(parsed.deletedAttendanceIds) ? parsed.deletedAttendanceIds : [],\n    deletedUserIds: Array.isArray(parsed.deletedUserIds) ? parsed.deletedUserIds : [],\n    deletedOperatorIds: Array.isArray(parsed.deletedOperatorIds) ? parsed.deletedOperatorIds : []\n  };\n}\n\nfunction loadState() {\n  try {\n    return normalizeState(JSON.parse(localStorage.getItem(STORAGE_KEY) || \"{}\"));\n  } catch {\n    return normalizeState();\n  }\n}\n\nfunction loadCurrentUser() {\n  try {\n    return JSON.parse(sessionStorage.getItem(SESSION_KEY) || \"null\");\n  } catch {\n    return null;\n  }\n}\n\nfunction saveState() {\n  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n  if (!serverBacked) return;\n  fetch(\"/api/state\", {\n    method: \"POST\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(state)\n  }).catch(() => {\n    serverBacked = false;\n    showToast(\"Server sync paused. Data is still saved in this browser.\");\n  });\n}\n\nasync function loadServerState() {\n  try {\n    const response = await fetch(\"/api/state\", { cache: \"no-store\" });\n    if (!response.ok) return;\n    state = normalizeState(await response.json());\n    serverBacked = true;\n    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n    applyLoginState();\n    renderAll();\n  } catch {\n    serverBacked = false;\n  } finally {\n    serverLoaded = true;\n    applyLoginState();\n  }\n}\n\nfunction groupKey(record) {\n  return [record.date, record.department, record.line, record.shift].join(\"::\");\n}\n\nfunction userCan(view) {\n  if (!currentUser) return false;\n  if (currentUser.role === \"admin\") return true;\n  return view === \"supervisor\" || view === \"blacklist\";\n}\n\nfunction selectedContext() {\n  if (currentUser?.role === \"supervisor\") {\n    return {\n      date: $(\"attendanceDate\").value || today,\n      department: currentUser.department,\n      line: currentUser.line,\n      shift: $(\"shiftSelect\").value,\n      supervisor: currentUser.name,\n      leaderId: currentUser.id\n    };\n  }\n\n  return {\n    date: $(\"attendanceDate\").value || today,\n    department: $(\"departmentSelect\").value,\n    line: $(\"lineSelect\").value,\n    shift: $(\"shiftSelect\").value,\n    supervisor: $(\"supervisorName\").value.trim() || currentUser?.name || \"Supervisor\",\n    leaderId: currentUser?.id || \"unknown\"\n  };\n}\n\nfunction showToast(message) {\n  const toast = $(\"toast\");\n  toast.textContent = message;\n  toast.classList.add(\"show\");\n  setTimeout(() => toast.classList.remove(\"show\"), 2400);\n}\n\nfunction unique(values) {\n  return [...new Set(values.filter(Boolean))].sort((a, b) => a.localeCompare(b));\n}\n\nfunction fillSelect(select, values) {\n  const previous = select.value;\n  select.innerHTML = \"\";\n  values.forEach((value) => {\n    const option = document.createElement(\"option\");\n    option.value = value;\n    option.textContent = value;\n    select.appendChild(option);\n  });\n  if (values.includes(previous)) select.value = previous;\n}\n\nfunction refreshFilters() {\n  const departments = currentUser?.role === \"supervisor\"\n    ? [currentUser.department]\n    : unique(state.operators.map((op) => op.department));\n  fillSelect($(\"departmentSelect\"), departments);\n  refreshLines();\n}\n\nfunction refreshLines() {\n  const dept = $(\"departmentSelect\").value;\n  const lines = currentUser?.role === \"supervisor\"\n    ? [currentUser.line]\n    : unique(state.operators.filter((op) => !dept || op.department === dept).map((op) => op.line));\n  fillSelect($(\"lineSelect\"), lines);\n  renderAll();\n}\n\nfunction parseCardText(text) {\n  const clean = text.trim();\n  if (!clean) return null;\n  const parts = clean.split(\"|\").map((part) => part.trim());\n\n  if (parts.length >= 5) {\n    const [code, name, skill, department, line, doj = \"\", skillLevel = \"\", issuedDate = \"\", renewDate = \"\"] = parts;\n    const operator = { code, name, skill, department, line, doj, skillLevel, issuedDate, renewDate };\n    upsertOperator(operator);\n    return operator;\n  }\n\n  return state.operators.find((op) => op.code.toLowerCase() === clean.toLowerCase()) || null;\n}\n\nfunction upsertOperator(operator) {\n  state.deletedOperatorIds = state.deletedOperatorIds.filter((id) => id.toLowerCase() !== operator.code.toLowerCase());\n  const index = state.operators.findIndex((op) => op.code.toLowerCase() === operator.code.toLowerCase());\n  if (index >= 0) {\n    state.operators[index] = { ...state.operators[index], ...operator };\n  } else {\n    state.operators.push(operator);\n  }\n}\n\nfunction replaceOperators(operators) {\n  const nextCodes = new Set(operators.map((operator) => operator.code.toLowerCase()));\n  const removedCodes = state.operators\n    .map((operator) => operator.code)\n    .filter((code) => code && !nextCodes.has(code.toLowerCase()));\n\n  state.deletedOperatorIds = unique([\n    ...state.deletedOperatorIds,\n    ...removedCodes\n  ]);\n  state.operators = operators;\n}\n\nfunction scanAttendance(text, source = \"Skill Card\") {\n  const now = Date.now();\n  const clean = text.trim();\n  if (!clean) return;\n  if (clean === lastScanValue && now - lastScanAt < 1200) return;\n  lastScanValue = clean;\n  lastScanAt = now;\n\n  const operator = parseCardText(clean);\n  if (!operator) {\n    showToast(\"ID not found in master. Ask admin to add/import this operator first.\");\n    return;\n  }\n\n  const context = selectedContext();\n  if (currentUser?.role === \"supervisor\" && (operator.department !== context.department || operator.line !== context.line)) {\n    showToast(`${operator.name} belongs to ${operator.department} / ${operator.line}. Not saved for this login.`);\n    return;\n  }\n\n  const duplicate = state.attendance.find((record) =>\n    record.date === context.date &&\n    record.shift === context.shift &&\n    record.code.toLowerCase() === operator.code.toLowerCase()\n  );\n  if (duplicate) {\n    $(\"lastScan\").innerHTML = `<strong>${escapeHtml(operator.name)}</strong><br>Already scanned today for shift ${escapeHtml(context.shift)}.`;\n    showToast(\"Already scanned. Duplicate not saved.\");\n    return;\n  }\n\n  const record = {\n    id: crypto.randomUUID(),\n    date: context.date,\n    time: new Date().toLocaleTimeString([], { hour: \"2-digit\", minute: \"2-digit\", second: \"2-digit\" }),\n    code: operator.code,\n    name: operator.name,\n    skill: operator.skill,\n    currentProcess: operator.skill,\n    doj: operator.doj || \"\",\n    skillLevel: operator.skillLevel || \"\",\n    issuedDate: operator.issuedDate || \"\",\n    renewDate: operator.renewDate || \"\",\n    department: operator.department || context.department,\n    line: operator.line || context.line,\n    shift: context.shift,\n    supervisor: context.supervisor,\n    leaderId: context.leaderId,\n    source,\n    status: \"Present\"\n  };\n\n  state.attendance.push(record);\n  saveState();\n  $(\"lastScan\").innerHTML = `<strong>${escapeHtml(operator.name)}</strong><br>${escapeHtml(operator.code)} · ${escapeHtml(operator.skill)} · saved automatically`;\n  $(\"scanInput\").value = \"\";\n  refreshFilters();\n  renderAll();\n}\n\nasync function toggleCamera() {\n  if (stream) {\n    stopCamera();\n    return;\n  }\n\n  if (!(\"BarcodeDetector\" in window)) {\n    showToast(\"Camera scanning is not supported here. Use a USB scanner or ID entry.\");\n    return;\n  }\n\n  try {\n    detector = new BarcodeDetector({ formats: [\"qr_code\", \"code_128\", \"code_39\", \"ean_13\"] });\n    stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: \"environment\" } });\n    $(\"scannerVideo\").srcObject = stream;\n    await $(\"scannerVideo\").play();\n    $(\"cameraEmpty\").classList.add(\"hidden\");\n    $(\"cameraBtn\").textContent = \"Stop Camera\";\n    scanning = true;\n    scanLoop();\n  } catch {\n    showToast(\"Camera permission was blocked or no camera is available.\");\n  }\n}\n\nfunction stopCamera() {\n  stream?.getTracks().forEach((track) => track.stop());\n  stream = null;\n  scanning = false;\n  $(\"scannerVideo\").srcObject = null;\n  $(\"cameraEmpty\").classList.remove(\"hidden\");\n  $(\"cameraBtn\").textContent = \"Start Camera\";\n}\n\nasync function scanLoop() {\n  if (!scanning || !detector) return;\n  try {\n    const codes = await detector.detect($(\"scannerVideo\"));\n    if (codes.length) {\n      scanAttendance(codes[0].rawValue, \"Camera Scan\");\n      await new Promise((resolve) => setTimeout(resolve, 650));\n    }\n  } catch {\n    // Some frames are not readable while the camera warms up.\n  }\n  requestAnimationFrame(scanLoop);\n}\n\nfunction scopedAttendance(records = state.attendance) {\n  if (currentUser?.role !== \"supervisor\") return records;\n  return records.filter((record) => record.department === currentUser.department && record.line === currentUser.line);\n}\n\nfunction currentLineRecords() {\n  const context = selectedContext();\n  return state.attendance.filter((record) =>\n    record.date === context.date &&\n    record.department === context.department &&\n    record.line === context.line &&\n    record.shift === context.shift\n  );\n}\n\nfunction renderAttendance() {\n  const records = currentLineRecords();\n  const required = state.operators.filter((op) =>\n    op.department === $(\"departmentSelect\").value && op.line === $(\"lineSelect\").value\n  ).length;\n\n  $(\"presentCount\").textContent = records.length;\n  $(\"requiredCount\").textContent = required;\n  $(\"gapCount\").textContent = Math.max(required - records.length, 0);\n\n  const skillCounts = records.reduce((acc, record) => {\n    acc[record.skill] = (acc[record.skill] || 0) + 1;\n    return acc;\n  }, {});\n  $(\"skillSummary\").innerHTML = Object.entries(skillCounts)\n    .map(([skill, count]) => `<div class=\"pill-row\"><span>${escapeHtml(skill)}</span><strong>${count}</strong></div>`)\n    .join(\"\") || `<div class=\"pill-row\"><span>No skill count yet</span><strong>0</strong></div>`;\n\n  $(\"attendanceRows\").innerHTML = records.map((record) => `\n    <tr>\n      <td>${escapeHtml(record.time)}</td>\n      <td>${escapeHtml(record.code)}</td>\n      <td>${escapeHtml(record.name)}</td>\n      <td>${escapeHtml(record.skill)}</td>\n      <td>${escapeHtml(record.department)}</td>\n      <td>${escapeHtml(record.line)}</td>\n      <td><span class=\"status present\">${escapeHtml(record.source || record.status)}</span></td>\n      <td><button class=\"mini-btn\" data-remove=\"${record.id}\">Remove</button></td>\n    </tr>\n  `).join(\"\") || `<tr><td colspan=\"8\">No attendance marked for this line yet.</td></tr>`;\n}\n\nfunction attendanceGroups() {\n  const groups = new Map();\n  scopedAttendance().forEach((record) => {\n    const key = groupKey(record);\n    if (!groups.has(key)) groups.set(key, []);\n    groups.get(key).push(record);\n  });\n  return [...groups.entries()].map(([key, records]) => ({ key, records, first: records[0] }))\n    .sort((a, b) => a.key.localeCompare(b.key));\n}\n\nfunction lineSessionsFor(operator, shift = \"all\") {\n  const sessions = new Set();\n  state.attendance.forEach((record) => {\n    const sameLine = record.department === operator.department && record.line === operator.line;\n    const sameShift = shift === \"all\" || record.shift === shift;\n    if (sameLine && sameShift) sessions.add(`${record.date}::${record.shift}`);\n  });\n  return [...sessions].sort();\n}\n\nfunction absenteeismFor(operator, shift = \"all\") {\n  const sessions = lineSessionsFor(operator, shift);\n  const present = new Set(\n    state.attendance\n      .filter((record) => record.code.toLowerCase() === operator.code.toLowerCase())\n      .filter((record) => shift === \"all\" || record.shift === shift)\n      .map((record) => `${record.date}::${record.shift}`)\n  );\n  const absentSessions = sessions.filter((session) => !present.has(session));\n  const absentPercent = sessions.length ? Math.round((absentSessions.length / sessions.length) * 1000) / 10 : 0;\n  return {\n    operator,\n    workingSessions: sessions.length,\n    presentSessions: present.size,\n    absentSessions,\n    absentCount: absentSessions.length,\n    absentPercent\n  };\n}\n\nfunction scopedOperators() {\n  if (currentUser?.role !== \"supervisor\") return state.operators;\n  return state.operators.filter((op) => op.department === currentUser.department && op.line === currentUser.line);\n}\n\nfunction absentSessionLabel(session) {\n  const [date, shift] = session.split(\"::\");\n  return `${date} (${shift})`;\n}\n\nfunction blacklistRows() {\n  return scopedOperators()\n    .map((operator) => absenteeismFor(operator, \"all\"))\n    .filter((item) => item.workingSessions > 0 && item.absentPercent > 20)\n    .sort((a, b) => b.absentPercent - a.absentPercent || b.absentCount - a.absentCount);\n}\n\nfunction renderQueryResult(operatorCode = $(\"queryInput\").value.trim()) {\n  const code = operatorCode.trim();\n  if (!code) {\n    $(\"queryResult\").innerHTML = `<span>Enter an Emp. ID to check attendance history.</span>`;\n    return;\n  }\n\n  const operator = state.operators.find((op) => op.code.toLowerCase() === code.toLowerCase());\n  if (!operator) {\n    $(\"queryResult\").innerHTML = `<strong>Emp. ID not found</strong><br><span>${escapeHtml(code)} is not available in master data.</span>`;\n    return;\n  }\n\n  if (currentUser?.role === \"supervisor\" && (operator.department !== currentUser.department || operator.line !== currentUser.line)) {\n    $(\"queryResult\").innerHTML = `<strong>Outside this login</strong><br><span>${escapeHtml(operator.name)} belongs to ${escapeHtml(operator.department)} / ${escapeHtml(operator.line)}.</span>`;\n    return;\n  }\n\n  const stats = absenteeismFor(operator, $(\"queryShift\").value);\n  const absentList = stats.absentSessions.map(absentSessionLabel).join(\", \") || \"No absent days in recorded attendance sessions.\";\n  $(\"queryResult\").innerHTML = `\n    <div class=\"query-person\">\n      <strong>${escapeHtml(operator.name)}</strong>\n      <span>${escapeHtml(operator.code)} · ${escapeHtml(operator.department)} / ${escapeHtml(operator.line)}</span>\n    </div>\n    <div class=\"metrics compact-metrics\">\n      <div class=\"metric\"><span>Working Sessions</span><strong>${stats.workingSessions}</strong></div>\n      <div class=\"metric\"><span>Absent</span><strong>${stats.absentCount}</strong></div>\n      <div class=\"metric\"><span>Absent %</span><strong>${stats.absentPercent}%</strong></div>\n    </div>\n    <div class=\"absent-list\"><strong>Absent days:</strong> ${escapeHtml(absentList)}</div>\n  `;\n}\n\nfunction renderAdmin() {\n  const records = scopedAttendance();\n  const groups = attendanceGroups();\n  $(\"adminTotal\").textContent = records.length;\n  $(\"adminLines\").textContent = groups.length;\n  $(\"adminOperators\").textContent = state.operators.length;\n\n  const deptCounts = records.reduce((acc, record) => {\n    acc[record.department] = (acc[record.department] || 0) + 1;\n    return acc;\n  }, {});\n  const max = Math.max(...Object.values(deptCounts), 1);\n  $(\"deptBars\").innerHTML = Object.entries(deptCounts).map(([dept, count]) => `\n    <div class=\"bar-row\">\n      <span>${escapeHtml(dept)}</span>\n      <progress max=\"${max}\" value=\"${count}\"></progress>\n      <strong>${count}</strong>\n    </div>\n  `).join(\"\") || `<div class=\"bar-row\"><span>No attendance yet</span><strong>0</strong></div>`;\n\n  $(\"adminRows\").innerHTML = groups.map(({ key, records: groupRecords, first }) => {\n    const skills = summarize(groupRecords.map((record) => record.skill));\n    const names = groupRecords.map((record) => record.name).join(\", \");\n    return `\n      <tr>\n        <td>${escapeHtml(first.date)}</td>\n        <td>${escapeHtml(first.department)}</td>\n        <td>${escapeHtml(first.line)}</td>\n        <td>${escapeHtml(first.shift)}</td>\n        <td>${groupRecords.length}</td>\n        <td>${escapeHtml(skills)}</td>\n        <td>${escapeHtml(names)}</td>\n      </tr>\n    `;\n  }).join(\"\") || `<tr><td colspan=\"8\">No compiled data yet.</td></tr>`;\n}\n\nfunction renderBlacklist() {\n  const rows = blacklistRows();\n  $(\"blacklistRows\").innerHTML = rows.map((item) => `\n    <tr>\n      <td>${escapeHtml(item.operator.code)}</td>\n      <td>${escapeHtml(item.operator.name)}</td>\n      <td>${escapeHtml(item.operator.department)}</td>\n      <td>${escapeHtml(item.operator.line)}</td>\n      <td>${item.workingSessions}</td>\n      <td>${item.absentCount}</td>\n      <td><span class=\"status risk\">${item.absentPercent}%</span></td>\n      <td>${escapeHtml(item.absentSessions.map(absentSessionLabel).join(\", \"))}</td>\n    </tr>\n  `).join(\"\") || `<tr><td colspan=\"8\">No one is above 20% absenteeism for recorded line sessions.</td></tr>`;\n}\n\nfunction renderMaster() {\n  $(\"masterRows\").innerHTML = state.operators.map((op) => `\n    <tr>\n      <td>${escapeHtml(op.code)}</td>\n      <td>${escapeHtml(op.name)}</td>\n      <td>${escapeHtml(op.skill)}</td>\n      <td>${escapeHtml(op.department)}</td>\n      <td>${escapeHtml(op.line)}</td>\n      <td>${escapeHtml(op.doj || \"\")}</td>\n      <td>${escapeHtml(op.skillLevel || \"\")}</td>\n    </tr>\n  `).join(\"\");\n}\n\nfunction renderUsers() {\n  const adminCount = state.users.filter((user) => user.role === \"admin\").length;\n  $(\"userRows\").innerHTML = state.users.map((user) => `\n    <tr>\n      <td>${escapeHtml(user.name)}</td>\n      <td>${escapeHtml(user.id)}</td>\n      <td>${escapeHtml(user.role)}</td>\n      <td>${escapeHtml(user.department || \"All\")}</td>\n      <td>${escapeHtml(user.line || \"All\")}</td>\n      <td>${canRemoveUser(user, adminCount) ? `<button class=\"mini-btn\" data-remove-user=\"${escapeHtml(user.id)}\">Remove</button>` : \"\"}</td>\n    </tr>\n  `).join(\"\");\n}\n\nfunction canRemoveUser(user, adminCount = state.users.filter((item) => item.role === \"admin\").length) {\n  if (currentUser?.id === user.id) return false;\n  if (user.role === \"admin\" && adminCount <= 1) return false;\n  return true;\n}\n\nfunction renderAll() {\n  renderAttendance();\n  renderAdmin();\n  renderBlacklist();\n  renderMaster();\n  renderUsers();\n}\n\nfunction summarize(values) {\n  const counts = values.reduce((acc, value) => {\n    acc[value] = (acc[value] || 0) + 1;\n    return acc;\n  }, {});\n  return Object.entries(counts).map(([value, count]) => `${value}: ${count}`).join(\"; \");\n}\n\nfunction escapeHtml(value) {\n  return String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({\n    \"&\": \"&amp;\",\n    \"<\": \"&lt;\",\n    \">\": \"&gt;\",\n    '\"': \"&quot;\",\n    \"'\": \"&#039;\"\n  })[char]);\n}\n\nfunction download(filename, content, type) {\n  const blob = new Blob([content], { type });\n  const url = URL.createObjectURL(blob);\n  const link = document.createElement(\"a\");\n  link.href = url;\n  link.download = filename;\n  document.body.appendChild(link);\n  link.click();\n  link.remove();\n  URL.revokeObjectURL(url);\n}\n\nfunction exportExcel() {\n  const rows = [\n    [\"Date\", \"Time\", \"Emp. ID\", \"Name\", \"Dept.\", \"Current Process\", \"Skill Level\", \"DOJ\", \"Issued Date\", \"Renew Date\", \"Line\", \"Shift\", \"Line Leader\", \"Leader Login\", \"Entry Source\"]\n  ];\n  scopedAttendance().forEach((record) => {\n    rows.push([\n      record.date,\n      record.time,\n      record.code,\n      record.name,\n      record.department,\n      record.currentProcess || record.skill,\n      record.skillLevel || \"\",\n      record.doj || \"\",\n      record.issuedDate || \"\",\n      record.renewDate || \"\",\n      record.line,\n      record.shift,\n      record.supervisor,\n      record.leaderId || \"\",\n      record.source || \"Skill Card\"\n    ]);\n  });\n\n  const html = `\n    <html><head><meta charset=\"utf-8\"></head><body>\n      <table>${rows.map((row) => `<tr>${row.map((cell) => `<td>${escapeHtml(cell)}</td>`).join(\"\")}</tr>`).join(\"\")}</table>\n    </body></html>\n  `;\n  download(`plant-attendance-${today}.xls`, html, \"application/vnd.ms-excel\");\n}\n\nfunction exportBackup() {\n  const backup = {\n    ...state,\n    users: state.users.map(({ password, ...user }) => ({\n      ...user,\n      hasPassword: Boolean(password)\n    }))\n  };\n  download(`plant-attendance-backup-${today}.json`, JSON.stringify(backup, null, 2), \"application/json\");\n}\n\nfunction exportBlacklist() {\n  const rows = [\n    [\"Emp. ID\", \"Name\", \"Department\", \"Line\", \"Working Sessions\", \"Absent\", \"Absent %\", \"Absent Days\"]\n  ];\n  blacklistRows().forEach((item) => {\n    rows.push([\n      item.operator.code,\n      item.operator.name,\n      item.operator.department,\n      item.operator.line,\n      item.workingSessions,\n      item.absentCount,\n      `${item.absentPercent}%`,\n      item.absentSessions.map(absentSessionLabel).join(\", \")\n    ]);\n  });\n  const html = `\n    <html><head><meta charset=\"utf-8\"></head><body>\n      <table>${rows.map((row) => `<tr>${row.map((cell) => `<td>${escapeHtml(cell)}</td>`).join(\"\")}</tr>`).join(\"\")}</table>\n    </body></html>\n  `;\n  download(`plant-blacklist-${today}.xls`, html, \"application/vnd.ms-excel\");\n}\n\nfunction parseCsv(text) {\n  const rows = [];\n  let row = [];\n  let cell = \"\";\n  let quoted = false;\n\n  for (let index = 0; index < text.length; index += 1) {\n    const char = text[index];\n    const next = text[index + 1];\n\n    if (char === '\"' && quoted && next === '\"') {\n      cell += '\"';\n      index += 1;\n    } else if (char === '\"') {\n      quoted = !quoted;\n    } else if (char === \",\" && !quoted) {\n      row.push(cell.trim());\n      cell = \"\";\n    } else if ((char === \"\\n\" || char === \"\\r\") && !quoted) {\n      if (char === \"\\r\" && next === \"\\n\") index += 1;\n      row.push(cell.trim());\n      if (row.some(Boolean)) rows.push(row);\n      row = [];\n      cell = \"\";\n    } else {\n      cell += char;\n    }\n  }\n\n  row.push(cell.trim());\n  if (row.some(Boolean)) rows.push(row);\n  return rows.filter((item) => item.length >= 5 && item[0]);\n}\n\nfunction setActiveView(view) {\n  if (!userCan(view)) {\n    view = \"supervisor\";\n  }\n  document.querySelectorAll(\".nav-tab\").forEach((tab) => {\n    const allowed = userCan(tab.dataset.view);\n    tab.hidden = !allowed;\n    tab.classList.toggle(\"active\", tab.dataset.view === view);\n  });\n  document.querySelectorAll(\".view\").forEach((section) => section.classList.remove(\"active\"));\n  $(`${view}View`).classList.add(\"active\");\n  $(\"viewTitle\").textContent = document.querySelector(`[data-view=\"${view}\"]`)?.textContent.trim() || \"Attendance\";\n}\n\nfunction applyLoginState() {\n  const loggedIn = Boolean(currentUser);\n  $(\"loginScreen\").classList.toggle(\"hidden\", loggedIn);\n  document.querySelector(\".app-shell\").classList.toggle(\"locked\", !loggedIn);\n  if (!loggedIn) {\n    const firstAdminMode = serverLoaded && state.users.length === 0;\n    $(\"loginBtn\").textContent = firstAdminMode ? \"Create First Admin\" : \"Login\";\n    $(\"loginHint\").textContent = firstAdminMode\n      ? \"No production login exists yet. Create the first admin before sharing the app link.\"\n      : \"Production logins are loaded from the Postgres database. Import existing users before plant use.\";\n    return;\n  }\n\n  $(\"currentUserLabel\").textContent = `${currentUser.name} (${currentUser.role})`;\n  $(\"currentScopeLabel\").textContent = currentUser.role === \"supervisor\"\n    ? `${currentUser.department} / ${currentUser.line}`\n    : \"All plant departments\";\n  $(\"departmentSelect\").disabled = currentUser.role === \"supervisor\";\n  $(\"lineSelect\").disabled = currentUser.role === \"supervisor\";\n  $(\"supervisorName\").value = currentUser.name;\n  const activeView = document.querySelector(\".nav-tab.active\")?.dataset.view || \"supervisor\";\n  refreshFilters();\n  setActiveView(activeView);\n}\n\nfunction login() {\n  const id = $(\"loginUser\").value.trim();\n  const password = $(\"loginPass\").value;\n  if (!serverLoaded && location.protocol.startsWith(\"http\")) {\n    showToast(\"Loading production login data. Try again in a moment.\");\n    loadServerState();\n    return;\n  }\n  if (!state.users.length) {\n    if (!id || !password) {\n      showToast(\"Enter first admin user ID and password.\");\n      return;\n    }\n    const user = {\n      name: id,\n      id,\n      password,\n      role: \"admin\",\n      department: \"All\",\n      line: \"All\"\n    };\n    state.users.push(user);\n    currentUser = user;\n    sessionStorage.setItem(SESSION_KEY, JSON.stringify(user));\n    saveState();\n    applyLoginState();\n    renderAll();\n    showToast(\"First admin login created.\");\n    return;\n  }\n  const user = state.users.find((item) => item.id === id && item.password === password);\n  if (!user) {\n    showToast(\"Login failed. Check user ID/password or import admin user into database.\");\n    return;\n  }\n  currentUser = user;\n  sessionStorage.setItem(SESSION_KEY, JSON.stringify(user));\n  applyLoginState();\n  renderAll();\n  $(\"scanInput\").focus();\n}\n\ndocument.querySelectorAll(\".nav-tab\").forEach((button) => {\n  button.addEventListener(\"click\", () => {\n    closeOptionsMenu();\n    loadServerState();\n    setActiveView(button.dataset.view);\n  });\n});\n\n$(\"loginBtn\").addEventListener(\"click\", login);\n$(\"loginPass\").addEventListener(\"keydown\", (event) => {\n  if (event.key === \"Enter\") login();\n});\n$(\"logoutBtn\").addEventListener(\"click\", () => {\n  currentUser = null;\n  sessionStorage.removeItem(SESSION_KEY);\n  stopCamera();\n  closeOptionsMenu();\n  applyLoginState();\n});\n\n$(\"menuBtn\").addEventListener(\"click\", () => {\n  const sidebar = document.querySelector(\".sidebar\");\n  const open = sidebar.classList.toggle(\"menu-open\");\n  $(\"menuBtn\").setAttribute(\"aria-expanded\", String(open));\n});\n\nfunction closeOptionsMenu() {\n  document.querySelector(\".sidebar\").classList.remove(\"menu-open\");\n  $(\"menuBtn\").setAttribute(\"aria-expanded\", \"false\");\n}\n\n$(\"departmentSelect\").addEventListener(\"change\", refreshLines);\n[\"lineSelect\", \"shiftSelect\", \"attendanceDate\"].forEach((id) => {\n  $(id).addEventListener(\"change\", renderAll);\n});\n\n$(\"scanInput\").addEventListener(\"keydown\", (event) => {\n  if (event.key === \"Enter\") scanAttendance(event.target.value, \"Skill Card\");\n});\n$(\"missedCardBtn\").addEventListener(\"click\", () => scanAttendance($(\"scanInput\").value, \"Missed Card ID\"));\n$(\"queryFromScanBtn\").addEventListener(\"click\", () => {\n  $(\"queryInput\").value = $(\"scanInput\").value.trim();\n  setActiveView(\"blacklist\");\n  renderQueryResult();\n});\n$(\"cameraBtn\").addEventListener(\"click\", toggleCamera);\n$(\"downloadBtn\").addEventListener(\"click\", exportExcel);\n$(\"backupBtn\").addEventListener(\"click\", exportBackup);\n$(\"queryBtn\").addEventListener(\"click\", () => renderQueryResult());\n$(\"queryInput\").addEventListener(\"keydown\", (event) => {\n  if (event.key === \"Enter\") renderQueryResult();\n});\n$(\"queryShift\").addEventListener(\"change\", () => renderQueryResult());\n$(\"downloadBlacklistBtn\").addEventListener(\"click\", exportBlacklist);\n\n$(\"attendanceRows\").addEventListener(\"click\", (event) => {\n  const id = event.target.dataset.remove;\n  if (!id) return;\n  const record = state.attendance.find((item) => item.id === id);\n  if (!window.confirm(`Remove attendance for ${record?.name || \"this operator\"}?`)) return;\n  state.deletedAttendanceIds.push(id);\n  state.attendance = state.attendance.filter((item) => item.id !== id);\n  saveState();\n  renderAll();\n});\n\n$(\"clearLineBtn\").addEventListener(\"click\", () => {\n  const records = currentLineRecords();\n  if (!records.length) return;\n  if (!window.confirm(`Clear ${records.length} attendance record(s) for this line and shift?`)) return;\n  const ids = new Set(records.map((record) => record.id));\n  state.deletedAttendanceIds.push(...ids);\n  state.attendance = state.attendance.filter((record) => !ids.has(record.id));\n  saveState();\n  renderAll();\n  showToast(\"Selected line attendance cleared.\");\n});\n\n$(\"sampleBtn\").addEventListener(\"click\", () => {\n  if (!window.confirm(\"Replace current operator master with sample data?\")) return;\n  replaceOperators(sampleOperators);\n  saveState();\n  refreshFilters();\n  showToast(\"Sample master loaded.\");\n});\n\n$(\"addOperatorBtn\").addEventListener(\"click\", () => {\n  const operator = {\n    code: $(\"newCode\").value.trim(),\n    name: $(\"newName\").value.trim(),\n    skill: $(\"newSkill\").value.trim(),\n    department: $(\"newDept\").value.trim(),\n    line: $(\"newLine\").value.trim(),\n    doj: $(\"newDoj\").value.trim(),\n    skillLevel: $(\"newSkillLevel\").value.trim()\n  };\n  if (!operator.code || !operator.name || !operator.department || !operator.line) {\n    showToast(\"Please enter code, name, department and line.\");\n    return;\n  }\n  upsertOperator(operator);\n  [\"newCode\", \"newName\", \"newSkill\", \"newDept\", \"newLine\", \"newDoj\", \"newSkillLevel\"].forEach((id) => $(id).value = \"\");\n  saveState();\n  refreshFilters();\n  showToast(\"Operator added to master.\");\n});\n\n$(\"masterFile\").addEventListener(\"change\", async (event) => {\n  const file = event.target.files[0];\n  if (!file) return;\n  const rows = parseCsv(await file.text());\n  const firstHeader = rows[0]?.[0]?.toLowerCase();\n  const hasHeader = firstHeader === \"code\" || firstHeader === \"emp_id\";\n  const dataRows = hasHeader ? rows.slice(1) : rows;\n  const importedOperators = dataRows.map(([code, name, department, line, skill, doj = \"\", skillLevel = \"\", issuedDate = \"\", renewDate = \"\"]) => ({\n    code,\n    name,\n    department,\n    line,\n    skill,\n    doj,\n    skillLevel,\n    issuedDate,\n    renewDate\n  }));\n  replaceOperators(importedOperators);\n  saveState();\n  refreshFilters();\n  showToast(`${state.operators.length} operators imported.`);\n});\n\n$(\"addUserBtn\").addEventListener(\"click\", () => {\n  const user = {\n    name: $(\"newLoginName\").value.trim(),\n    id: $(\"newLoginId\").value.trim(),\n    password: $(\"newLoginPass\").value.trim(),\n    role: $(\"newLoginRole\").value,\n    department: $(\"newLoginDept\").value.trim() || \"All\",\n    line: $(\"newLoginLine\").value.trim() || \"All\"\n  };\n  if (!user.name || !user.id || !user.password) {\n    showToast(\"Enter name, user ID and password.\");\n    return;\n  }\n  if (user.role === \"supervisor\" && (!user.department || user.department === \"All\" || !user.line || user.line === \"All\")) {\n    showToast(\"Line leader login needs department and line.\");\n    return;\n  }\n  state.users = state.users.filter((item) => item.id !== user.id);\n  state.users.push(user);\n  [\"newLoginName\", \"newLoginId\", \"newLoginPass\", \"newLoginDept\", \"newLoginLine\"].forEach((id) => $(id).value = \"\");\n  saveState();\n  renderUsers();\n  showToast(\"Login created.\");\n});\n\n$(\"userRows\").addEventListener(\"click\", (event) => {\n  const id = event.target.dataset.removeUser;\n  if (!id) return;\n  const user = state.users.find((item) => item.id === id);\n  if (!user || !canRemoveUser(user)) {\n    showToast(\"This login cannot be removed while it is protecting admin access.\");\n    renderUsers();\n    return;\n  }\n  if (!window.confirm(`Remove login ${id}?`)) return;\n  state.deletedUserIds.push(id);\n  state.users = state.users.filter((user) => user.id !== id);\n  saveState();\n  renderUsers();\n});\n\nrefreshFilters();\napplyLoginState();\nrenderAll();\nloadServerState();\n","type":"application/javascript; charset=utf-8"},"/operator-master-template.csv":{"body":"emp_id,name,department,line,current_process,doj,skill_level,issued_date,renew_date\n303408,Sample Operator,Production,Assembly-K2,F/A,14-07-2025,Level 4,23-04-2026,22-07-2026\nOP1001,Asha Patel,Assembly,Line 1,Welding,,,,\nOP1002,Ravi Shah,Assembly,Line 1,Fitting,,,,\n","type":"text/csv; charset=utf-8"},"/index.html":{"body":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Plant Attendance</title>\n    <link rel=\"stylesheet\" href=\"styles.css\">\n  </head>\n  <body>\n    <section class=\"login-screen\" id=\"loginScreen\">\n      <div class=\"login-panel\">\n        <div class=\"brand compact\">\n          <div class=\"brand-mark\">PA</div>\n          <div>\n            <h1>Plant Attendance</h1>\n            <p>Secure line-wise login</p>\n          </div>\n        </div>\n        <div class=\"login-form\">\n          <label>\n            User ID\n            <input id=\"loginUser\" autocomplete=\"username\" placeholder=\"User ID\">\n          </label>\n          <label>\n            Password\n            <input id=\"loginPass\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Password\">\n          </label>\n          <button class=\"primary-btn\" id=\"loginBtn\">Login</button>\n        </div>\n        <p class=\"hint\" id=\"loginHint\">Production logins are loaded from the Postgres database. Import existing users before plant use.</p>\n      </div>\n    </section>\n\n    <div class=\"app-shell\">\n      <aside class=\"sidebar\">\n        <button class=\"menu-btn\" id=\"menuBtn\" type=\"button\" aria-expanded=\"false\" aria-label=\"Options menu\" title=\"Options menu\">\n          <span></span>\n          <span></span>\n          <span></span>\n        </button>\n\n        <div class=\"brand\">\n          <div class=\"brand-mark\">PA</div>\n          <div>\n            <h1>Plant Attendance</h1>\n            <p>Line-wise daily manpower</p>\n          </div>\n        </div>\n\n        <nav class=\"nav-tabs\" aria-label=\"Main views\">\n          <button class=\"nav-tab active\" data-view=\"supervisor\" title=\"Supervisor attendance\">\n            <span>Scan</span>\n          </button>\n          <button class=\"nav-tab\" data-view=\"admin\" title=\"Admin dashboard\">\n            <span>Admin</span>\n          </button>\n          <button class=\"nav-tab\" data-view=\"blacklist\" title=\"Absenteeism check\">\n            <span>Blacklist</span>\n          </button>\n          <button class=\"nav-tab\" data-view=\"master\" title=\"Operator master\">\n            <span>Master</span>\n          </button>\n        </nav>\n\n        <div class=\"sidebar-card user-card\">\n          <span class=\"label\">Logged in</span>\n          <strong id=\"currentUserLabel\">Not logged in</strong>\n          <small id=\"currentScopeLabel\"></small>\n          <button class=\"ghost-btn\" id=\"logoutBtn\">Logout</button>\n        </div>\n\n        <div class=\"sidebar-card\">\n          <span class=\"label\">Today</span>\n          <strong id=\"todayLabel\"></strong>\n          <small>All records are saved on this device and can be exported.</small>\n        </div>\n      </aside>\n\n      <main>\n        <header class=\"topbar\">\n          <div>\n            <p class=\"eyebrow\">Morning attendance</p>\n            <h2 id=\"viewTitle\">Supervisor Scan</h2>\n          </div>\n          <div class=\"topbar-actions\">\n            <button class=\"ghost-btn\" id=\"backupBtn\" title=\"Download all backup data\">Backup</button>\n            <button class=\"primary-btn\" id=\"downloadBtn\" title=\"Download Excel-readable attendance file\">Download Excel</button>\n          </div>\n        </header>\n\n        <section class=\"view active\" id=\"supervisorView\">\n          <div class=\"toolbar\">\n            <label>\n              Date\n              <input type=\"date\" id=\"attendanceDate\">\n            </label>\n            <label>\n              Department\n              <select id=\"departmentSelect\"></select>\n            </label>\n            <label>\n              Line\n              <select id=\"lineSelect\"></select>\n            </label>\n            <label>\n              Shift\n              <select id=\"shiftSelect\">\n                <option>A</option>\n                <option>B</option>\n                <option>C</option>\n                <option>General</option>\n              </select>\n            </label>\n            <label>\n              Line Leader\n              <input id=\"supervisorName\" placeholder=\"Name\" readonly>\n            </label>\n          </div>\n\n          <div class=\"scan-grid\">\n            <section class=\"panel scanner-panel\">\n              <div class=\"panel-head\">\n                <div>\n                  <h3>Skill Card Scanner</h3>\n                  <p>Each skill card is saved automatically after scan.</p>\n                </div>\n                <button class=\"ghost-btn\" id=\"cameraBtn\" title=\"Start camera scanning\">Start Camera</button>\n              </div>\n\n              <div class=\"camera-wrap\">\n                <video id=\"scannerVideo\" muted playsinline></video>\n                <div class=\"scan-frame\"></div>\n                <div class=\"camera-empty\" id=\"cameraEmpty\">Camera scanner ready</div>\n              </div>\n\n              <div class=\"quick-entry\">\n                <input id=\"scanInput\" placeholder=\"Scanner ready for Emp. ID\">\n                <button class=\"primary-btn\" id=\"missedCardBtn\">Missed Card ID</button>\n                <button class=\"ghost-btn\" id=\"queryFromScanBtn\">Query</button>\n              </div>\n\n              <div class=\"last-scan\" id=\"lastScan\">\n                <span>No operator scanned yet.</span>\n              </div>\n            </section>\n\n            <section class=\"panel\">\n              <div class=\"panel-head\">\n                <div>\n                  <h3>Current Line Count</h3>\n                  <p>Live count for selected date, shift, department and line.</p>\n                </div>\n              </div>\n              <div class=\"metrics\">\n                <div class=\"metric\">\n                  <span>Present</span>\n                  <strong id=\"presentCount\">0</strong>\n                </div>\n                <div class=\"metric\">\n                  <span>Required</span>\n                  <strong id=\"requiredCount\">0</strong>\n                </div>\n                <div class=\"metric\">\n                  <span>Gap</span>\n                  <strong id=\"gapCount\">0</strong>\n                </div>\n              </div>\n              <div class=\"skill-summary\" id=\"skillSummary\"></div>\n            </section>\n          </div>\n\n          <section class=\"panel table-panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Line Attendance</h3>\n                <p>Names remain available as backup for admin.</p>\n              </div>\n              <button class=\"danger-btn\" id=\"clearLineBtn\">Clear Line</button>\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Time</th>\n                    <th>Emp. ID</th>\n                    <th>Name</th>\n                    <th>Current Process</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th>Status</th>\n                    <th></th>\n                  </tr>\n                </thead>\n                <tbody id=\"attendanceRows\"></tbody>\n              </table>\n            </div>\n          </section>\n        </section>\n\n        <section class=\"view\" id=\"blacklistView\">\n          <section class=\"panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Punctuality Query</h3>\n                <p>Scan or enter Emp. ID to see absent days.</p>\n              </div>\n              <button class=\"primary-btn\" id=\"queryBtn\">Query</button>\n            </div>\n            <div class=\"query-line\">\n              <input id=\"queryInput\" placeholder=\"Emp. ID, e.g. 303408\">\n              <select id=\"queryShift\">\n                <option value=\"all\">All Shifts</option>\n                <option>A</option>\n                <option>B</option>\n                <option>C</option>\n                <option>General</option>\n              </select>\n            </div>\n            <div id=\"queryResult\" class=\"query-result\">\n              <span>Enter an Emp. ID to check attendance history.</span>\n            </div>\n          </section>\n\n          <section class=\"panel table-panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Blacklist Over 20%</h3>\n                <p>Based on absenteeism in recorded line attendance sessions.</p>\n              </div>\n              <button class=\"ghost-btn\" id=\"downloadBlacklistBtn\">Download Blacklist</button>\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Emp. ID</th>\n                    <th>Name</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th>Working Sessions</th>\n                    <th>Absent</th>\n                    <th>Absent %</th>\n                    <th>Absent Days</th>\n                  </tr>\n                </thead>\n                <tbody id=\"blacklistRows\"></tbody>\n              </table>\n            </div>\n          </section>\n        </section>\n\n        <section class=\"view\" id=\"adminView\">\n          <div class=\"admin-grid\">\n            <section class=\"panel\">\n              <div class=\"panel-head\">\n                <div>\n                  <h3>Plant Summary</h3>\n                  <p>Compiled line-wise manpower count.</p>\n                </div>\n              </div>\n              <div class=\"metrics wide\">\n                <div class=\"metric\"><span>Total Present</span><strong id=\"adminTotal\">0</strong></div>\n                <div class=\"metric\"><span>Lines Covered</span><strong id=\"adminLines\">0</strong></div>\n                <div class=\"metric\"><span>Operators</span><strong id=\"adminOperators\">0</strong></div>\n              </div>\n            </section>\n            <section class=\"panel\">\n              <div class=\"panel-head\">\n                <div>\n                  <h3>Department Count</h3>\n                  <p>Ready for morning manpower review.</p>\n                </div>\n              </div>\n              <div id=\"deptBars\" class=\"bars\"></div>\n            </section>\n          </div>\n\n          <section class=\"panel table-panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Compiled Attendance</h3>\n                <p>Line totals with backup names available in export.</p>\n              </div>\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Date</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th>Shift</th>\n                    <th>Present</th>\n                    <th>Processes</th>\n                    <th>Names</th>\n                  </tr>\n                </thead>\n                <tbody id=\"adminRows\"></tbody>\n              </table>\n            </div>\n          </section>\n\n          <section class=\"panel table-panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Login Control</h3>\n                <p>Admin creates department and line-leader access.</p>\n              </div>\n              <button class=\"primary-btn\" id=\"addUserBtn\">Create Login</button>\n            </div>\n            <div class=\"operator-form login-create\">\n              <input id=\"newLoginName\" placeholder=\"Leader/Admin name\">\n              <input id=\"newLoginId\" placeholder=\"User ID\">\n              <input id=\"newLoginPass\" placeholder=\"Password\">\n              <select id=\"newLoginRole\">\n                <option value=\"supervisor\">Line Leader</option>\n                <option value=\"admin\">Admin</option>\n              </select>\n              <input id=\"newLoginDept\" placeholder=\"Department\">\n              <input id=\"newLoginLine\" placeholder=\"Line\">\n            </div>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Name</th>\n                    <th>User ID</th>\n                    <th>Role</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th></th>\n                  </tr>\n                </thead>\n                <tbody id=\"userRows\"></tbody>\n              </table>\n            </div>\n          </section>\n        </section>\n\n        <section class=\"view\" id=\"masterView\">\n          <section class=\"panel\">\n            <div class=\"panel-head\">\n              <div>\n                <h3>Operator Master</h3>\n                <p>Import your employee list or add operators manually.</p>\n              </div>\n              <button class=\"ghost-btn\" id=\"sampleBtn\">Load Sample Master</button>\n            </div>\n            <div class=\"master-actions\">\n              <label class=\"file-import\">\n                Import CSV\n                <input type=\"file\" id=\"masterFile\" accept=\".csv,text/csv\">\n              </label>\n              <button class=\"primary-btn\" id=\"addOperatorBtn\">Add Operator</button>\n            </div>\n            <div class=\"operator-form\">\n              <input id=\"newCode\" placeholder=\"Emp. ID\">\n              <input id=\"newName\" placeholder=\"Name\">\n              <input id=\"newSkill\" placeholder=\"Current Process\">\n              <input id=\"newDept\" placeholder=\"Department\">\n              <input id=\"newLine\" placeholder=\"Line\">\n              <input id=\"newDoj\" placeholder=\"DOJ\">\n              <input id=\"newSkillLevel\" placeholder=\"Skill Level\">\n            </div>\n            <p class=\"hint\">CSV columns: emp_id, name, department, line, current_process, doj, skill_level, issued_date, renew_date. Your sample QR decodes to Emp. ID only, so details are pulled from master data.</p>\n            <div class=\"table-wrap\">\n              <table>\n                <thead>\n                  <tr>\n                    <th>Emp. ID</th>\n                    <th>Name</th>\n                    <th>Current Process</th>\n                    <th>Department</th>\n                    <th>Line</th>\n                    <th>DOJ</th>\n                    <th>Skill Level</th>\n                  </tr>\n                </thead>\n                <tbody id=\"masterRows\"></tbody>\n              </table>\n            </div>\n          </section>\n        </section>\n      </main>\n    </div>\n\n    <div class=\"toast\" id=\"toast\"></div>\n    <script src=\"app.js\"></script>\n  </body>\n</html>\n","type":"text/html; charset=utf-8"}};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/api/state" && request.method === "GET") {
      return json({ operators: [], attendance: [], users: [] });
    }
    if (url.pathname === "/api/state" && request.method === "POST") {
      return json({ ok: true });
    }
    const route = routes[url.pathname] || routes["/"];
    return new Response(route.body, { headers: { "Content-Type": route.type } });
  }
};

function json(value) {
  return new Response(JSON.stringify(value), {
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" }
  });
}